import { axiosInstance } from './axiosInstance';
import { Prediction } from '../types';

export interface PredictionQueryParams {
  component?: string;
  status?: string;
}

/**
 * Prediction API Client - STRICTLY READ-ONLY (GET endpoints only)
 * Predictions are generated by the upstream Python ML / Airflow batch pipeline.
 */
export const predictionApi = {
  getPredictions: async (params?: PredictionQueryParams): Promise<Prediction[]> => {
    const response = await axiosInstance.get<Prediction[]>('/api/predictions', { params });
    return response.data;
  },

  getAll: async (params?: PredictionQueryParams): Promise<Prediction[]> => {
    return predictionApi.getPredictions(params);
  },

  getLatestPredictions: async (): Promise<Prediction[]> => {
    const response = await axiosInstance.get<Prediction[]>('/api/predictions/latest');
    return response.data;
  },

  getLatestForAll: async (): Promise<Prediction[]> => {
    return predictionApi.getLatestPredictions();
  },

  getMachinePredictions: async (machineId: number): Promise<Prediction[]> => {
    const response = await axiosInstance.get<Prediction[]>(`/api/machines/${machineId}/predictions`);
    return response.data;
  },

  getByMachineId: async (machineId: number): Promise<Prediction[]> => {
    return predictionApi.getMachinePredictions(machineId);
  },

  getLatestMachinePrediction: async (machineId: number): Promise<Prediction> => {
    const response = await axiosInstance.get<Prediction>(`/api/machines/${machineId}/predictions/latest`);
    return response.data;
  },

  getLatestByMachineId: async (machineId: number): Promise<Prediction> => {
    return predictionApi.getLatestMachinePrediction(machineId);
  },
};
